"""Explain bit assertions and software/hardware KASAN check scope."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1669': ('점검표에서 일부 칸만 골라 확인한 뒤 선택 표시를 지운다고 생각해 보세요. 이어지는 한 번의 확인에 대한 가정까지 붙어 있으므로 작업 순서가 중요해요.', '비트 assertion의 네 단계와 다음 접근의 가정을 이해합니다.', 'mask 설정 → ASSERT 검사 → mask를 0으로 해제 → atomic_next(1)을 적으세요. 그 다음 줄에 READ_ONCE(flags) & mask를 놓으세요.', ['ASSERT_EXCLUSIVE_BITS는 선택한 비트에 다른 동시 쓰기가 없어야 한다는 조건을 검사해요. 비트는 0 또는 1인 칸이고 mask는 검사할 칸을 고르는 표시예요. 다른 읽기는 허용하며 선택 밖 비트의 접근은 이 조건 검사에서 제외해요.', '먼저 kcsan_set_access_mask(mask)로 검사 범위를 정해요. 다음에는 대상 주소 &(var), 크기 sizeof(var), ASSERT 표시를 검사 함수에 전달해요. 검사할 비트를 고른 것이지 대상 숫자를 마스크 값으로 덮어쓴 것은 아니에요.', '그 뒤 kcsan_set_access_mask(0)으로 선택 비트 제한을 해제해요. 마지막에는 kcsan_atomic_next(1)을 호출해요. 이는 다음 한 메모리 접근을 검사 도구가 원자적으로 간주하도록 알리는 표시예요.', '왜 다음 접근을 따로 표시할까요? 문서는 바로 다음 접근이 선택한 비트만 사용한다는 가정 아래 낙관적으로 안전하게 취급한다고 설명해요. 중간에 엉뚱한 접근을 끼워 넣으면 그 가정과 코드가 어긋날 수 있어요.', '예를 들어 mask가 0x0f이고 flags가 0xa5이면 READ_ONCE(flags) & mask는 하위 네 비트 0101, 즉 5를 뽑아요. &는 양쪽 모두 켜진 비트만 남기는 AND예요. 검사할 조건과 실제로 읽어 사용할 비트가 연결돼야 해요.', 'KCSAN이 다음 접근을 낙관적으로 취급한다고 모든 컴파일러 변환까지 안전하다는 증명은 아니에요. 원문은 비트 조작 최적화를 모두 추론할 수 없으므로 READ_ONCE가 여전히 바람직할 수 있다고 설명해요. 실제 쓰기에는 필요한 잠금·원자 갱신 규칙도 따로 지켜야 해요.'], [('비트 assertion의 검사 뒤 마지막 두 단계는 무엇인가요?', ['mask를 계속 유지하고 모든 접근을 원자적으로 표시해요', 'mask를 0으로 해제한 다음 atomic_next(1)을 호출해요'], '정답은 두 번째예요. 선택 범위를 해제한 뒤 다음 한 접근에 대한 표시를 넣어요. 마스크가 뒤의 모든 검사에 계속 적용되거나 모든 접근이 원자적으로 바뀌는 것은 아니에요.'), ('KCSAN이 다음 접근을 안전하게 취급하면 READ_ONCE가 언제나 필요 없어지나요?', ['아니요. 컴파일러의 비트 최적화 때문에 여전히 바람직할 수 있어요', '네. 모든 컴파일러 변환의 안전성이 이미 증명됐어요'], '정답은 첫 번째예요. 검사 도구의 가정과 실제 컴파일러가 코드를 바꾸는 규칙은 달라요. 원문도 모든 비트 최적화를 추론할 수 없으므로 READ_ONCE 사용을 주의 깊게 고려하라고 설명해요.')]), 'os1670': ('창고에서 물건을 꺼내기 전에 그 선반을 사용해도 되는지 확인하는 것과 비슷해요. 주소 검사도 실제 데이터를 읽는 일과 구별해야 해요.', '소프트웨어 KASAN의 직접 검사 조건과 헤더 사용 제한을 이해합니다.', 'KASAN_GENERIC 또는 KASAN_SW_TAGS → 직접 검사 함수 선언, 둘 다 아님 → true 반환 대체 함수를 그리세요.', ['KASAN은 범위를 벗어나거나 해제된 메모리에 접근하는 문제 등을 찾는 검사 도구예요. 앞에서 배운 KCSAN의 동시 접근 검사와 이름은 비슷하지만 살피는 문제의 초점이 달라요.', '이 kasan-checks.h의 접근 표시는 컴파일러 계측을 사용하는 소프트웨어 KASAN을 위한 것이에요. 계측은 검사를 수행할 호출 등을 코드에 붙이는 일이에요. KASAN이라는 이름 아래의 모든 모드가 같은 경로를 쓰지는 않아요.', 'CONFIG_KASAN_GENERIC 또는 CONFIG_KASAN_SW_TAGS가 정의되어 있으면 __kasan_check_read와 __kasan_check_write를 bool 반환 함수로 선언해요. 또는 조건이므로 두 설정이 모두 있어야 하는 것은 아니에요. bool은 참·거짓을 나타내는 자료형이에요.', '두 함수는 대상 주소 p와 접근 크기 size를 받아요. read는 읽을 접근, write는 쓸 접근을 검사하는 이름이에요. 검사를 요청한다고 원래 하려던 데이터 복사나 값 저장까지 대신 실행해 주는 것은 아니에요.', '이 소프트웨어 조건이 아니라면 같은 직접 이름을 true만 반환하는 inline 함수로 제공해요. 이를 빈 대체 구현이라고 볼 수 있어요. 직접 함수 이름이 있다는 사실만으로 실제 소프트웨어 검사를 실행했다고 판단하면 안 돼요.', '직접 __kasan 경로는 해당 소프트웨어 KASAN이 켜진 상태에서 현재 C 파일의 계측만 선택적으로 꺼도 명시적으로 검사를 부르는 데 쓸 수 있어요. 그러나 원문은 이 직접 호출을 헤더에서 사용하지 말라고 해요. 여러 파일에 포함되는 헤더에서는 파일의 계측 설정을 따르는 공개 계층과 구별해야 해요.'], [('직접 소프트웨어 KASAN 검사 함수를 선언하는 조건은 무엇인가요?', ['여러 CPU를 지원하는 CONFIG_SMP만 있으면 돼요', 'CONFIG_KASAN_GENERIC 또는 CONFIG_KASAN_SW_TAGS예요'], '정답은 두 번째예요. 원문의 전처리 조건은 이 두 소프트웨어 모드를 OR로 연결해요. CPU 개수 설정이나 하드웨어 태그 모드를 같은 조건으로 읽으면 안 돼요.'), ('직접 __kasan_check_*를 공통 헤더에서 사용하라는 안내인가요?', ['아니요. 원문은 헤더에서 사용하지 말라고 해요', '네. 모든 헤더에서 직접 검사를 강제하라고 해요'], '정답은 첫 번째예요. 직접 호출은 현재 파일의 계측 선택과 다르게 동작할 수 있어요. 원문은 직접 계층과 헤더에 사용할 수 있는 공개 계층을 구분해요.')]), 'os1671': ('점검을 생략하는 창구가 늘 통과라고 답하도록 되어 있다면 그 답만으로 실제 점검을 했다고 말할 수 없어요. 반환값이 어디서 왔는지를 봐야 해요.', '공개 KASAN의 파일별 선택과 true 대체 반환을 구별합니다.', '__SANITIZE_ADDRESS__ 있음 → 직접 API 별칭, 없음 → return true를 적으세요. 반환값과 검사 수행 여부를 별도 칸에 기록하세요.', ['kasan_check_read와 kasan_check_write는 앞에 밑줄 두 개가 없는 공개 이름이에요. 현재 번역 단위에 __SANITIZE_ADDRESS__가 있는지에 따라 연결이 달라져요. 번역 단위는 보통 C 파일 하나와 포함한 헤더를 함께 번역하는 코드 덩어리예요.', '표시가 있으면 공개 read는 __kasan_check_read, 공개 write는 __kasan_check_write의 별칭이 돼요. 별칭은 같은 코드 이름으로 이어 주는 전처리 규칙이에요. 직접 경로의 소프트웨어 모드 조건도 함께 봐야 해요.', '표시가 없으면 공개 함수의 본문은 return true예요. true는 참이라는 bool 값이에요. 이 대체 함수에는 주소를 실제 검사하는 동작이 없으므로 참이라는 결과만 보고 주소가 안전하다고 확인됐다고 할 수 없어요.', '예를 들어 커널의 소프트웨어 KASAN 지원은 켰지만 어떤 파일의 주소 계측은 껐을 수 있어요. 그 파일에서 공개 이름은 대체 함수를 사용할 수 있어요. 전체 기능 설정과 현재 파일의 검사 경로를 별도로 확인해야 하는 이유예요.', '주소 계측의 __SANITIZE_ADDRESS__와 스레드 계측의 __SANITIZE_THREAD__는 다른 표시예요. ADDRESS는 메모리 접근 유효성 검사 쪽, THREAD는 앞의 KCSAN 공개 계층에서 본 조건이에요. 비슷한 철자만 보고 바꾸어 읽지 않아요.', '또 이 대체 구현은 함수이므로 인자의 부수 효과는 C 평가 규칙을 따라요. 검사 본문이 없다는 말이 인자에 적은 값 변경까지 무조건 사라진다는 뜻은 아니에요. 중요한 데이터 갱신은 검사 인자에 숨기지 않고 따로 적으면 이해하기 쉬워요.'], [('공개 KASAN 접근 이름을 직접 검사 이름으로 연결하는 현재 파일 표시는 무엇인가요?', ['언제나 __SANITIZE_THREAD__예요', '__SANITIZE_ADDRESS__예요'], '정답은 두 번째예요. 헤더의 #ifdef는 ADDRESS 표시를 확인해요. THREAD 표시는 다른 계측 조건이므로 KCSAN에서 본 이름과 혼동하지 마세요.'), ('대체 함수에서 true가 반환되면 실제 주소 검사를 통과한 것인가요?', ['아니요. 검사 없이 true를 돌려주는 구성일 수 있어요', '네. 모든 주소의 안전성을 확인했다는 뜻이에요'], '정답은 첫 번째예요. 이쪽 본문은 검사 호출 없이 return true예요. 결과 숫자나 참·거짓만이 아니라 어떤 구현이 선택되어 실행됐는지 확인해야 해요.')]), 'os1672': ('같은 학교 검사라도 사람이 확인하는 방식과 기계가 표지를 확인하는 방식은 다를 수 있어요. 같은 이름의 도구라고 사용 경로가 모두 같은 것은 아니에요.', '소프트웨어와 하드웨어 태그 KASAN의 인터페이스 범위를 구별합니다.', '소프트웨어 모드: 이 헤더의 접근 검사 / 하드웨어 태그 모드: kasan_check_byte 안내를 두 칸에 적으세요.', ['tag는 데이터를 구별하기 위해 붙이는 표지예요. 하드웨어 태그 기반 KASAN은 하드웨어의 태그 검사 기능을 활용하는 모드예요. 컴파일러가 소프트웨어 검사 코드를 넣는 방식과 실행 경로가 달라요.', 'kasan-checks.h 첫 주석은 이 파일의 접근 annotation이 소프트웨어 KASAN 모드에 관련된다고 설명해요. annotation은 검사에 필요한 호출이나 정보를 코드에 붙이는 표시예요.', '같은 주석은 하드웨어 태그 모드에서는 이 표시들이 최적화로 사라진다고 설명해요. 그래서 소스에 kasan_check_read나 write 이름이 보인다는 사실만으로 그 모드에서 실제 검사가 실행됐다고 말할 수 없어요.', '원문은 하드웨어 태그 모드의 해당 검사 용도로 kasan_check_byte를 사용하라고 안내해요. byte는 바이트를 뜻해요. 이 안내만으로 그 함수가 임의 크기의 범위를 모두 검사한다고 넓혀 추측하지 않고, 실제 사용할 때는 그 함수의 조건과 범위를 확인해야 해요.', 'kcsan_atomic_next는 앞에서 본 KCSAN의 다음 접근 분류 도구예요. 이름이 비슷해도 KASAN 하드웨어 태그 검사 함수가 아니에요. KASAN·KCSAN과 소프트웨어·하드웨어 모드를 먼저 구별하세요.', '소프트웨어 검사 호출을 흉내 낸 모델을 시험했다고 하드웨어 태그 검사 엔진도 검증한 것은 아니에요. 어떤 모드의 어떤 함수와 입력을 실제로 확인했는지 기록해야 해요. 이 수업은 헤더의 적용 범위와 안내를 읽는 단계예요.'], [('이 헤더 주석은 하드웨어 태그 모드에서 어떤 검사 함수로 안내하나요?', ['kcsan_atomic_next예요', 'kasan_check_byte예요'], '정답은 두 번째예요. 헤더의 첫 주석에 그 안내가 있어요. kcsan_atomic_next는 KCSAN이 다음 접근을 해석하는 표시이므로 하드웨어 태그 검사와 같은 기능이 아니에요.'), ('소프트웨어 접근 검사 모델을 확인하면 하드웨어 태그 엔진 검증도 끝난 것인가요?', ['아니요. 적용 모드와 실행 경로가 달라요', '네. KASAN이라는 이름이 같으면 내부 동작도 같아요'], '정답은 첫 번째예요. 같은 KASAN 아래에서도 컴파일러 계측과 하드웨어 태그 경로는 달라요. 실제로 시험하지 않은 모드의 동작까지 모델 결과로 증명할 수는 없어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_413.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
